This Terraform program creates a DynamoDB table and enables DynamoDB Contributor Insights for that specific table. The table uses on-demand billing, server-side encryption, point-in-time recovery, TTL, and tags. Contributor Insights is enabled through the `aws_dynamodb_contributor_insights` resource with configurable defaults.

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region where the DynamoDB table and Contributor Insights resource will be created."
  type        = string
  default     = "us-east-1"
}

variable "table_name" {
  description = "Name of the DynamoDB table for which Contributor Insights will be enabled."
  type        = string
  default     = "custom-contributor-insights-table"
}

variable "contributor_insights_enabled" {
  description = "Whether DynamoDB Contributor Insights should be enabled for the table."
  type        = bool
  default     = true
}

